function [Mp_AC, phi_AC, VcClk, vcRegulated, VsClk, regCapture, k, it, vcRegHistory] = fcn_regulate_Vc(vcReg, Mp_AC, phi_AC, VcClkRef, k)
%FCN_REGULATE_VC corrects the AC source command Mp_AC and phi_AC [rad]
%until v_c is back to its no-load phasor VcClkRef (switch must be CLOSED).
%The converter (Mp, phi_m) is not changed. Same algorithm as fcn_regulate_vc
%of fcn_step1_PQ_fullbridge_smallestconstraint_v3 (simulation).
%   v_s is generated by a power amplifier + transformer, and the switch
%   closed after the sync adds a voltage drop between v_s and v_c, so the
%   voltage seen by the converter changes with the current. Regulating v_c
%   (instead of v_s) gives the converter an ideal grid at its terminals.
%   The DAC output (amplifier input) is measured on the same PicoScope as v_c,
%   so the DAC phasor gives the internal oscillator phase within each capture.
%   Adding phi_AC (known) gives the phase of v_c relative to the internal
%   oscillator (VcClk), which is also the reference of phi_m of the converter.
%
%   The AC source command is the phasor Es = Mp_AC*exp(j*phi_AC). The gain
%   k = dVc/dEs between Es and v_c depends on the impedances between them and
%   the converter (amplifier + transformer + switch): v_c is driven by both
%   the AC source and the converter, so k is not Vc/Es. It is measured from
%   the last two iterations (secant) and returned, to be used as first guess
%   at the next point (k barely changes from one point to the next). If k is
%   empty (or not given), the first correction assumes k = Vc/Es.
%
%   VcClkRef: v_c phasor in the oscillator frame to hold (taken at no load,
%   at the end of the sync).
%
%   vcReg: struct with the devices (ts, ps4000aDeviceObj, numChannels,
%   probeVoltsPerUnit, idxVc, idxVs, idxVdac, dtScope, f0) and the tuning
%   (TolV, TolPhi, Alpha, MaxStepM, MaxStepPhi, MaxIter, Settle_s, Mmax, Vmax).
%
%   Returns the Mp_AC/phi_AC of the last capture (applied to the board), the
%   last measured VcClk, whether the tolerances were met, VsClk (v_s in the
%   oscillator frame, same last capture) to quantify the voltage drop
%   |V_s - V_c| across the switch, printed at the end, the last capture
%   regCapture (fields t, v_c, v_dac, Mp_AC, phi_AC) to compare it with the
%   sync reference (fcn_plot_vc_regulation), the gain k and the number of
%   iterations it.
%   vcRegHistory: one value per iteration (capture) - Mp_AC, phi_AC [rad]
%   applied, VcClk measured, Vc_rms [V rms], ephi [rad] phase error and k
%   gain used for the next correction (NaN at the last iteration)

if nargin < 5
    k = []; %gain dVc/dEs unknown
end

clip = @(x, lim) min(max(x, -lim), lim); %limits x to [-lim, lim]

Mp_AC_start = Mp_AC;
phi_AC_start = phi_AC;
vcRegulated = false;
vcRegHistory.Mp_AC = NaN(1, vcReg.MaxIter);
vcRegHistory.phi_AC = NaN(1, vcReg.MaxIter);
vcRegHistory.VcClk = NaN(1, vcReg.MaxIter);
vcRegHistory.Vc_rms = NaN(1, vcReg.MaxIter);
vcRegHistory.ephi = NaN(1, vcReg.MaxIter);
vcRegHistory.k = NaN(1, vcReg.MaxIter);

for it = 1:vcReg.MaxIter

    vcReg.ts.write("Config", struct("wMpAC", Mp_AC));
    vcReg.ts.write("Config", struct("wphi_AC", phi_AC));
    Mp_AC_meas = Mp_AC; %AC source values of this capture
    phi_AC_meas = phi_AC;
    Es = Mp_AC*exp(1j*phi_AC); %AC source command phasor of this capture
    pause(vcReg.Settle_s);

    [~, ~, channelData, ~] = picoscope_acquisition(vcReg.ps4000aDeviceObj, vcReg.numChannels);
    Vc = fcn_FundamentalPhasor(channelData{vcReg.idxVc} / vcReg.probeVoltsPerUnit(vcReg.idxVc), vcReg.dtScope, vcReg.f0);
    Vs = fcn_FundamentalPhasor(channelData{vcReg.idxVs} / vcReg.probeVoltsPerUnit(vcReg.idxVs), vcReg.dtScope, vcReg.f0);
    Vdac = fcn_FundamentalPhasor(channelData{vcReg.idxVdac} / vcReg.probeVoltsPerUnit(vcReg.idxVdac), vcReg.dtScope, vcReg.f0);

    %keep this capture with the AC source command applied during it
    regCapture.v_c = channelData{vcReg.idxVc} / vcReg.probeVoltsPerUnit(vcReg.idxVc);
    regCapture.v_dac = channelData{vcReg.idxVdac} / vcReg.probeVoltsPerUnit(vcReg.idxVdac);
    regCapture.t = (0:numel(regCapture.v_c) - 1).' * vcReg.dtScope;
    regCapture.Mp_AC = Mp_AC;
    regCapture.phi_AC = phi_AC;

    %v_c and v_s phasors in the internal oscillator frame: removes the random
    %phase of the capture start (via the DAC phasor) and adds the known DAC phase
    VcClk = Vc * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC);
    VsClk = Vs * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC);
    ephi = angle(VcClk/VcClkRef); % > 0 : v_c leads its reference

    vcRegHistory.Mp_AC(it) = Mp_AC;
    vcRegHistory.phi_AC(it) = phi_AC;
    vcRegHistory.VcClk(it) = VcClk;
    vcRegHistory.Vc_rms(it) = abs(VcClk);
    vcRegHistory.ephi(it) = ephi;

    fprintf('Vc reg %2d | Mp_AC %.4f, phi_AC %+.4f rad | Vc %.3f V rms (ref %.3f) | phase error %+.4f deg\n', ...
        it, Mp_AC, phi_AC, abs(VcClk), abs(VcClkRef), rad2deg(ephi));

    %safety: v_c too high, AC source back to its values before the regulation
    if abs(VcClk) > vcReg.Vmax
        vcReg.ts.write("Config", struct("wMpAC", Mp_AC_start));
        vcReg.ts.write("Config", struct("wphi_AC", phi_AC_start));
        error('Vc regulation aborted: v_c above %.1f V rms, Mp_AC and phi_AC set back to their values before the regulation.', vcReg.Vmax);
    end

    if abs(abs(VcClk)-abs(VcClkRef)) < vcReg.TolV && abs(ephi) < vcReg.TolPhi
        vcRegulated = true;
        break
    end

    %gain k = dVc/dEs
    if it > 1 && Es ~= Es_prev
        k = (VcClk-Vc_prev)/(Es-Es_prev); %measured from the last two iterations
    elseif isempty(k)
        k = VcClk/Es; %first correction without previous point: v_c follows the AC source one to one
    end
    vcRegHistory.k(it) = k;
    Vc_prev = VcClk;
    Es_prev = Es;

    Es_new = Es + vcReg.Alpha*(VcClkRef-VcClk)/k; %AC source phasor that brings v_c to VcClkRef
    step_Mp_Es =  clip(abs(Es_new)-Mp_AC, vcReg.MaxStepM);
    Mp_AC = Mp_AC + step_Mp_Es; %amplitude, limited to MaxStepM per iteration
    Mp_AC = min(max(Mp_AC, 0), vcReg.Mmax); %DAC range (Mp_AC above ~0.96 clips the DAC)
    
    step_phi_Es = clip(angle(Es_new/Es), vcReg.MaxStepPhi);
    phi_AC = mod(phi_AC + step_phi_Es + pi, 2*pi) - pi; %phase kept in (-pi,pi]
end

%keep only the iterations done
names = fieldnames(vcRegHistory);
for n = 1:numel(names)
    vcRegHistory.(names{n}) = vcRegHistory.(names{n})(1:it);
end

%return the AC source values of the last capture (last update not applied if not regulated)
Mp_AC = Mp_AC_meas;
phi_AC = phi_AC_meas;

if ~vcRegulated
    warning('Vc regulation: tolerances not met after %d iteration(s).', vcReg.MaxIter);
end

%voltage drop between v_s and v_c (switch + cables), from the last capture
fprintf('Switch drop | V_s = %.2f V rms, V_c = %.2f V rms | |V_s - V_c| = %.3f V rms | phase(V_s) - phase(V_c) = %+.3f deg\n', ...
    abs(VsClk), abs(VcClk), abs(VsClk - VcClk), rad2deg(angle(VsClk / VcClk)));

end
